ll norm(ll x, int m) {
    x %= m;
    if (x < 0) x += m;
    return x;
}

ll modpow(ll x, ll n, int m) {
    x = norm(x, m);
    if (n == 0) return 1 % m;
    ll u = modpow(x, n / 2, m);
    u = u * u % m;
    if (n % 2) u = u * x % m;
    return u;
}

int phi(int n) {
    int res = n;
    for (int p = 2; p <= n / p; p++) {
        if (n % p) continue;
        while (n % p == 0) n /= p;
        res = res / p * (p - 1);
    }
    if (n > 1) res = res / n * (n - 1);
    return res;
}

