                    divs.push_back(divs[u] * pw);
                }
            }
            cnt *= j - i + 1;
            sum *= s;
            phi = phi / p * (p - 1);
            i = j;
        }
        for (ll d : divs) {
            if (fits && prod <= LLONG_MAX / d) prod *= d;
            else fits = false;
        }
    }
};

